import React from "react";
import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";
import { useAuth } from "../context/AuthContext";
import { APP_INFO } from "../constants/AppConstants";
import "./CardPage.css";

export default function CardPage() {
  const { user, isGuest } = useAuth();
  const navigate = useNavigate();

  return (
    <div>
      <Navbar />
      <div className="page-shell">
        <h3 className="section-title">Student Card</h3>

        {isGuest ? (
          <div className="card-lock">
            Sign in with your student account to view your Virtual Student Card and QR access code.
            <div style={{ marginTop: 14 }}>
              <button className="btn btn-primary btn-sm" onClick={() => navigate("/login")}>Sign in</button>
            </div>
          </div>
        ) : (
          <>
            <div className="card-wrap">
              <div className="student-card">
                <div className="card-top">
                  <div className="card-logo"><span>campus</span><span>Mobi</span></div>
                  <span className="card-role">{user?.role || "Student"}</span>
                </div>
                <div className="card-body">
                  <div className="card-name">{user?.fullName}</div>
                  <div className="card-id">{APP_INFO.UNIVERSITY}</div>
                  <div className="card-bottom">
                    <div className="card-qr" aria-label="QR access code" />
                    <div className="card-meta">
                      <strong>{user?.studentId}</strong>
                      Valid — session token active
                    </div>
                  </div>
                </div>
              </div>
            </div>
            <div className="card-actions">
              <button className="btn btn-ghost">Download</button>
              <button className="btn btn-primary">Show at scanner</button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
